<?php
/* GLP Atlas contact form mailer (generated by build.py). Works on Hostinger and any PHP host with mail().
   Spam protection: honeypot field, minimum fill time, per-IP rate limit, header-injection filtering. */
declare(strict_types=1);
const TO_MAIN  = 'contact@glpatlas.com';
const TO_ALT   = 'glp1atlas@gmail.com';
const FROM     = 'contact@glpatlas.com';        // must be a mailbox on your own domain (create it in Hostinger > Emails)
const SITE     = 'GLP Atlas';
const BACK     = '/contact/';
const THANKS   = '/contact/thanks/';

function go(string $to): void { header('Location: ' . $to, true, 303); exit; }
function clean(string $s, int $max): string { return mb_substr(trim(str_replace(["\r", "\n", "\0"], ' ', $s)), 0, $max); }

if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') go(BACK);
if (!empty($_POST['bot-field'])) go(THANKS);                                 // bots fill the hidden field: pretend success
$ts = (int)($_POST['ts'] ?? 0);
if ($ts > 0 && (time() - intdiv($ts, 1000)) < 3) go(THANKS);                  // submitted faster than a human can type

$ip = $_SERVER['REMOTE_ADDR'] ?? '0';
$bucket = sys_get_temp_dir() . '/glpatlas_' . md5($ip);
$hits = array_filter(explode(',', (string)@file_get_contents($bucket)), fn($t) => (int)$t > time() - 3600);
if (count($hits) >= 5) go(BACK . '?form=limit#form');
$hits[] = (string)time();
@file_put_contents($bucket, implode(',', $hits), LOCK_EX);

$name    = clean((string)($_POST['name'] ?? ''), 120);
$email   = clean((string)($_POST['email'] ?? ''), 200);
$topic   = clean((string)($_POST['topic'] ?? 'Message'), 60);
$message = mb_substr(trim((string)($_POST['message'] ?? '')), 0, 5000);
if ($name === '' || $message === '' || !filter_var($email, FILTER_VALIDATE_EMAIL)) go(BACK . '?form=invalid#form');

$subject = '=?UTF-8?B?' . base64_encode('[' . SITE . '] ' . $topic . ' — ' . $name) . '?=';
$body = "Name: $name\nEmail: $email\nTopic: $topic\nIP: $ip\nDate: " . date('c') . "\n\n$message\n";
$headers = implode("\r\n", [
    'From: ' . SITE . ' <' . FROM . '>',
    'Reply-To: ' . $email,
    'Cc: ' . TO_ALT,
    'MIME-Version: 1.0',
    'Content-Type: text/plain; charset=UTF-8',
    'X-Mailer: GLPAtlas',
]);
$ok = mail(TO_MAIN, $subject, $body, $headers, '-f' . FROM);
go($ok ? THANKS : BACK . '?form=error#form');
